	AccessibilityElement* ae = rid_owner.get_or_null(p_id);
	ERR_FAIL_NULL(ae);
	_ensure_node(p_id, ae);

	ae->name = p_name;
	String full_name = (ae->name + " " + ae->name_extra_info).strip_edges();
